"use client";

import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { StreamingText } from "./StreamingText";
import { TypingIndicator, type TypingIndicatorVariant } from "./TypingIndicator";

// One turn in a chat. The two sides are different objects, the way the best chat apps do it:
// - user: a raised bubble on the right with a small curl off its corner (the Chat FAQ bubble).
// - assistant: no surface at all, just text on the page, full width, with an optional avatar in a
//   socket beside it. Long answers read like a document instead of a stack of balloons.
//
// `status` walks an assistant turn through its life: typing (dots, before the first token) →
// streaming (words land as `content` grows) → done, or error (a danger line and a Retry). Pass
// `children` instead of `content` for rich content (markdown, code); it renders as is.
//
// Messages come and go with one movement: they rise 8px and fade in (a user bubble also grows from
// its tail corner) and fade up and away on exit. Wrap a list in <AnimatePresence initial={false}>
// so history doesn't animate on load but new turns do. Under reduced motion they only fade.

export type MessageFrom = "user" | "assistant";
export type MessageStatus = "typing" | "streaming" | "done" | "error";
export type MessageSize = "sm" | "md" | "lg";

type MotionConflicts = "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd";

export interface MessageProps extends Omit<HTMLAttributes<HTMLDivElement>, "content" | "children" | MotionConflicts> {
  from: MessageFrom;
  /** The text. On an assistant turn it streams in while `status` is "streaming". */
  content?: string;
  /** Rich content in place of `content`, rendered as is. */
  children?: ReactNode;
  /** Default "done". */
  status?: MessageStatus;
  /** Assistant only: an icon or image, set in a round socket beside the text. */
  avatar?: ReactNode;
  /** Read by screen readers before the message. Defaults to "You" or "Assistant". */
  name?: string;
  /** A row under the message (copy, regenerate…), shown once it's done. */
  actions?: ReactNode;
  /** Assistant only: what shows while waiting for the first token. Default "dots". */
  typingIndicator?: TypingIndicatorVariant;
  /** Error message for status "error". Default "Something went wrong." */
  error?: ReactNode;
  /** Shows a Retry button next to the error. */
  onRetry?: () => void;
  /** Blink a caret after the last word while streaming. Default true. */
  caret?: boolean;
  /** Default "md". */
  size?: MessageSize;
}

const EASE = [0.32, 0.72, 0, 1] as const;
const EASE_IN = [0.4, 0, 1, 1] as const;

const BUBBLE =
  "inset 0 1.5px 0 0 rgba(255,255,255,0.08), inset 0 -1px 0 0 rgba(0,0,0,0.5), 0 14px 30px -10px rgba(0,0,0,0.5), 0 1px 4px -1px rgba(0,0,0,0.35)";

const SIZES = {
  sm: { text: "text-[13px] leading-relaxed", pad: "px-3.5 py-2", avatar: "size-7 [&_svg]:size-3.5", gap: "gap-2.5" },
  md: { text: "text-[14.5px] leading-relaxed", pad: "px-4 py-2.5", avatar: "size-8 [&_svg]:size-4", gap: "gap-3" },
  lg: { text: "text-base leading-relaxed", pad: "px-5 py-3", avatar: "size-9 [&_svg]:size-[18px]", gap: "gap-3.5" },
} as const;

export const Message = forwardRef<HTMLDivElement, MessageProps>(function Message(
  {
    from,
    content,
    children,
    status = "done",
    avatar,
    name,
    actions,
    typingIndicator = "dots",
    error,
    onRetry,
    caret = true,
    size = "md",
    className,
    ...rest
  },
  ref
) {
  const reduce = useReducedMotion() ?? false;
  const s = SIZES[size];
  const isUser = from === "user";
  const label = name ?? (isUser ? "You" : "Assistant");

  const body =
    children ??
    (content === undefined ? null : isUser ? (
      <p className="whitespace-pre-wrap break-words">{content}</p>
    ) : (
      <StreamingText text={content} streaming={status === "streaming"} caret={caret} />
    ));

  return (
    <motion.div
      {...rest}
      ref={ref}
      role="article"
      aria-label={label}
      aria-busy={status === "typing" || status === "streaming" || undefined}
      data-from={from}
      data-state={status}
      initial={reduce ? { opacity: 0 } : { opacity: 0, y: 8, scale: isUser ? 0.97 : 1 }}
      animate={{ opacity: 1, y: 0, scale: 1, transition: { duration: reduce ? 0.15 : 0.26, ease: EASE } }}
      exit={{ opacity: 0, y: reduce ? 0 : -4, transition: { duration: 0.18, ease: EASE_IN } }}
      style={{ transformOrigin: isUser ? "100% 100%" : "0% 0%" }}
      className={cn("flex w-full", isUser ? "flex-col items-end pl-[12%]" : cn("items-start", s.gap), className)}
    >
      {isUser ? (
        <>
          <div className="relative mr-[11px] max-w-full">
            <div
              className={cn(
                "rounded-3xl rounded-br-none border border-white/[0.08] border-t-white/[0.13] bg-[#151516] text-neutral-200",
                s.pad,
                s.text
              )}
              style={{ boxShadow: BUBBLE }}
            >
              {body}
            </div>
            {/* Tail: a small curl off the bottom-right corner. */}
            <svg aria-hidden="true" width="12" height="16" viewBox="0 0 12 16" className="absolute -right-[11px] bottom-0 overflow-visible">
              <path d="M0 0 L1 0 C1 8 4.5 13 11.5 15.5 L11.5 16 L0 16 Z" fill="#151516" />
              <path d="M0.5 0 C0.5 8 4.5 13 11.5 15.5 L0 15.5" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="1" />
            </svg>
          </div>
          {actions && <div className="mt-1.5 mr-[11px] flex items-center gap-1">{actions}</div>}
        </>
      ) : (
        <>
          {avatar && (
            <span
              aria-hidden="true"
              className={cn(
                "grid shrink-0 place-items-center overflow-hidden rounded-full border border-white/[0.06] bg-[#070707] text-neutral-300",
                "shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]",
                s.avatar
              )}
            >
              {avatar}
            </span>
          )}
          <div className={cn("min-w-0 flex-1 text-neutral-300", s.text, avatar && "pt-[0.2em]")}>
            {status === "typing" ? (
              <TypingIndicator variant={typingIndicator} size={size} />
            ) : (
              body
            )}
            {status === "error" && (
              <div className={cn("flex flex-wrap items-center gap-x-3 gap-y-1.5", (children != null || content) && "mt-2")}>
                <p role="alert" className="flex items-start gap-1.5 text-[13px] leading-snug text-[rgb(229_115_115)]">
                  <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true" className="mt-[2px] shrink-0">
                    <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.4" />
                    <path d="M8 4.75v3.75" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
                    <circle cx="8" cy="11" r="0.9" fill="currentColor" />
                  </svg>
                  <span>{error ?? "Something went wrong."}</span>
                </p>
                {onRetry && (
                  <button
                    type="button"
                    onClick={onRetry}
                    className={cn(
                      "inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-lg px-2.5 text-[13px] font-medium tracking-tight text-neutral-200",
                      "border border-white/[0.08] border-t-white/[0.14] bg-[linear-gradient(180deg,#202022_0%,#19191b_100%)]",
                      "shadow-[inset_0_1px_0_rgba(255,255,255,0.07),inset_0_-1px_0_rgba(0,0,0,0.5),0_2px_6px_-1px_rgba(0,0,0,0.6)]",
                      "transition-[background,box-shadow,translate] duration-150 hover:bg-[linear-gradient(180deg,#252527_0%,#1c1c1e_100%)] hover:text-white",
                      "active:translate-y-px active:shadow-[inset_0_3px_8px_rgba(0,0,0,0.75),inset_0_1px_0_rgba(255,255,255,0.02)] motion-reduce:active:translate-y-0",
                      "outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1"
                    )}
                  >
                    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true">
                      <path d="M13 8a5 5 0 1 1-1.46-3.54" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
                      <path d="M13 2.5V5h-2.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    Retry
                  </button>
                )}
              </div>
            )}
            {actions && status === "done" && <div className="mt-2 -ml-1.5 flex items-center gap-1">{actions}</div>}
          </div>
        </>
      )}
    </motion.div>
  );
});

"use client";

import React, { forwardRef, useEffect, useRef, useState, type HTMLAttributes } from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

// Text that arrives a word at a time. Each word fades up out of a soft blur, and because the words
// overlap as they land, the line reads as one smooth wave rather than a series of pops.
//
// Model streams arrive in bursts: three words, a pause, five words. Showing them as they come is
// what makes streaming look jerky. So nothing is shown as it arrives. Incoming words wait in a
// buffer and are let out on a steady beat (`wordInterval`); when the buffer runs long the beat
// quickens so the text never falls far behind the stream. A word is only let out once it's whole
// (followed by a space, or the stream has ended), so half-words never appear and then change.
//
// Two ways to feed it:
// - Live (default): pass the text as it grows. Whatever is there when it mounts is history and
//   shows at once; only words that arrive afterwards land.
// - Reveal: pass the finished text with `reveal` and it plays itself in from the first word.
//
// Blank lines become paragraphs, single newlines become line breaks. While words are still coming,
// an optional caret blinks after the last one: the one thing here allowed to pulse, because it is
// live. Under reduced motion there's no pacing and no blur; words just fade in. In reveal mode
// screen readers get the full text immediately; the stream is visual only.

export interface StreamingTextProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** The text so far (live) or the whole text (reveal). */
  text: string;
  /** Play `text` in word by word on its own. Off: follow `text` as it grows. */
  reveal?: boolean;
  /** The beat words are let out on, in ms. Live streams quicken it when they fall behind. Default 32. */
  wordInterval?: number;
  /** Live only: more text is still coming. Until it's false, a trailing word without a space is held back. */
  streaming?: boolean;
  /** Blink a caret after the last word while words are still coming. Default true. */
  caret?: boolean;
  /** Reveal only: called once the last word has been let out. */
  onComplete?: () => void;
}

// A word fades in and its blur clears over 600ms. At a ~32ms beat that's about twenty words
// mid-landing at once, which is what makes it read as a wave.
const LAND_MS = 600;
const LAND_EASE = "cubic-bezier(0.25, 0.46, 0.45, 0.94)";
// Every this many words waiting in the buffer, the beat runs one step faster.
const CATCH_UP = 12;

interface Token {
  word: string;
  paragraph: number;
  /** First word of a new line inside its paragraph. */
  lineStart: boolean;
}

function tokenize(text: string): Token[] {
  const tokens: Token[] = [];
  text
    .trim()
    .split(/\n\s*\n/)
    .forEach((paragraph, p) =>
      paragraph.split("\n").forEach((line, l) =>
        line
          .split(/\s+/)
          .filter(Boolean)
          .forEach((word, w) => tokens.push({ word, paragraph: p, lineStart: l > 0 && w === 0 }))
      )
    );
  return tokens;
}

/** Words in `text` that are safe to show: mid-stream, a last word with no space after it may still be growing. */
export function countWords(text: string, streaming: boolean) {
  const total = text.match(/\S+/g)?.length ?? 0;
  return streaming && total > 0 && !/\s$/.test(text) ? total - 1 : total;
}

/**
 * The pacer: lets words out one per beat until it has caught up with `available`, quickening the
 * beat when it falls behind. Returns how many are out. Live mode starts with everything out;
 * reveal starts from zero, and again whenever `restartKey` changes.
 */
export function usePacedWords(
  available: number,
  { reveal = false, wordInterval = 32, restartKey }: { reveal?: boolean; wordInterval?: number; restartKey?: unknown }
) {
  const reduce = useReducedMotion() ?? false;
  const [visible, setVisible] = useState(() => (reveal && !reduce ? 0 : available));
  const shown = useRef(visible);

  const [played, setPlayed] = useState(restartKey);
  if (reveal && restartKey !== played) {
    setPlayed(restartKey);
    setVisible(0);
    shown.current = 0;
  }

  useEffect(() => {
    if (shown.current > available) {
      shown.current = available;
      setVisible(available);
    }
    if (reduce) {
      shown.current = available;
      setVisible(available);
      return;
    }
    if (shown.current >= available) return;

    let frame = 0;
    let last = performance.now();
    let owed = 0;
    const step = (now: number) => {
      owed += now - last;
      last = now;
      let next = shown.current;
      while (next < available) {
        const beat = Math.max(4, wordInterval / Math.max(1, (available - next) / CATCH_UP));
        if (owed < beat) break;
        owed -= beat;
        next += 1;
      }
      if (next !== shown.current) {
        shown.current = next;
        setVisible(next);
      }
      if (next < available) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [available, reduce, wordInterval, played]);

  return { visible: Math.min(visible, available), reduce, played };
}

// Runs once per element: the dataset flag survives the ref being re-attached on later renders.
export function land(el: HTMLElement | null, reduce: boolean) {
  if (!el || el.dataset.landed !== undefined) return;
  el.dataset.landed = "";
  if (reduce) {
    el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 150, easing: "linear" });
    return;
  }
  el.style.willChange = "opacity, filter, transform";
  const animation = el.animate(
    [
      { opacity: 0, filter: "blur(8px)", transform: "translateY(3px)" },
      { opacity: 0.7, filter: "blur(2px)", transform: "translateY(1px)", offset: 0.45 },
      { opacity: 1, filter: "blur(0px)", transform: "none" },
    ],
    { duration: LAND_MS, easing: LAND_EASE }
  );
  animation.onfinish = () => {
    el.style.willChange = "";
  };
}

function blink(el: HTMLElement | null) {
  if (!el || el.dataset.blinking !== undefined) return;
  el.dataset.blinking = "";
  el.animate([{ opacity: 1 }, { opacity: 1, offset: 0.5 }, { opacity: 0, offset: 0.55 }, { opacity: 0 }], {
    duration: 1000,
    iterations: Infinity,
  });
}

export const StreamingText = forwardRef<HTMLDivElement, StreamingTextProps>(function StreamingText(
  { text, reveal = false, wordInterval = 32, streaming = false, caret = true, onComplete, className, ...rest },
  ref
) {
  const tokens = tokenize(text);
  const total = tokens.length;
  const available = countWords(text, !reveal && streaming);

  // Words let out so far; a new text in reveal mode plays again from the start.
  const { visible, reduce, played } = usePacedWords(available, { reveal, wordInterval, restartKey: text });
  // Live mode: words already out on mount render still, without landing.
  const settled = useRef(reveal ? 0 : visible);

  const completed = useRef(onComplete);
  completed.current = onComplete;
  const finished = visible >= total;
  useEffect(() => {
    if (reveal && finished) completed.current?.();
  }, [reveal, finished, played]);

  const out = Math.min(visible, total);
  const live = reveal ? out < total : streaming || out < total;
  const lastParagraph = out > 0 ? tokens[out - 1].paragraph : 0;

  const paragraphs: React.ReactNode[][] = [];
  tokens.slice(0, out).forEach((token, i) => {
    const words = (paragraphs[token.paragraph] ??= []);
    if (token.lineStart) words.push(<br key={`br-${i}`} />);
    else if (words.length > 0) words.push(" ");
    words.push(
      i < settled.current ? (
        <React.Fragment key={i}>{token.word}</React.Fragment>
      ) : (
        <span
          key={i}
          ref={(el) => {
            land(el, reduce);
          }}
          className="inline-block"
        >
          {token.word}
        </span>
      )
    );
  });

  const caretMark = (
    <span
      key="caret"
      aria-hidden="true"
      ref={(el) => {
        blink(el);
      }}
      className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[0.18em] rounded-full bg-neutral-300"
    />
  );

  return (
    <div {...rest} ref={ref} data-state={live ? "streaming" : "done"} className={cn("break-words", className)}>
      {reveal && (
        <div className="sr-only">
          {text
            .trim()
            .split(/\n\s*\n/)
            .map((p, i) => (
              <p key={i}>{p}</p>
            ))}
        </div>
      )}
      <div aria-hidden={reveal || undefined}>
        {paragraphs.map((words, p) =>
          words ? (
            <p key={p} className={p > 0 ? "mt-3" : undefined}>
              {words}
              {caret && live && p === lastParagraph && caretMark}
            </p>
          ) : null
        )}
        {caret && live && out === 0 && <p>{caretMark}</p>}
      </div>
    </div>
  );
});

"use client";

import { forwardRef, type HTMLAttributes } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

// Shows the assistant is working before any words arrive. Two forms:
// - dots: three small dots breathing in turn, lifted straight from the Chat FAQ bubble.
// - shimmer: a label ("Thinking") with a band of light passing across it, left to right.
// Both are live states, so both may move; neither glows. Under reduced motion the dots keep their
// slow fade (it's opacity only) and the shimmer becomes a gentle fade of the whole label.
// It's a status region, so screen readers hear the label once.

export type TypingIndicatorVariant = "dots" | "shimmer";
export type TypingIndicatorSize = "sm" | "md" | "lg";

export interface TypingIndicatorProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** Default "dots". */
  variant?: TypingIndicatorVariant;
  /** Default "md". */
  size?: TypingIndicatorSize;
  /** Shown by the shimmer, read by screen readers for both. Default "Thinking". */
  label?: string;
}

const SIZES = {
  sm: { dot: "size-1", gap: "gap-1", text: "text-[13px]" },
  md: { dot: "size-[5px]", gap: "gap-1.5", text: "text-sm" },
  lg: { dot: "size-1.5", gap: "gap-2", text: "text-[15px]" },
} as const;

// Dim text with a brighter band in the middle of a wide background; sliding the background moves
// the band across the letters.
const SHIMMER =
  "bg-[linear-gradient(90deg,#737373_0%,#737373_40%,#e5e5e5_50%,#737373_60%,#737373_100%)] bg-[length:250%_100%] bg-clip-text text-transparent";

export const TypingIndicator = forwardRef<HTMLSpanElement, TypingIndicatorProps>(function TypingIndicator(
  { variant = "dots", size = "md", label = "Thinking", className, ...rest },
  ref
) {
  const reduce = useReducedMotion() ?? false;
  const s = SIZES[size];

  return (
    <span
      {...rest}
      ref={ref}
      role="status"
      data-variant={variant}
      className={cn("inline-flex items-center", className)}
    >
      {variant === "dots" ? (
        <>
          <span aria-hidden="true" className={cn("inline-flex h-[1.5em] items-center", s.gap)}>
            {[0, 1, 2].map((d) => (
              <motion.span
                key={d}
                className={cn("rounded-full bg-neutral-400", s.dot)}
                initial={{ opacity: 0.25 }}
                animate={{ opacity: [0.25, 1, 0.25] }}
                transition={{ duration: reduce ? 1.6 : 1, repeat: Infinity, delay: d * 0.16, ease: "easeInOut" }}
              />
            ))}
          </span>
          <span className="sr-only">{label}</span>
        </>
      ) : (
        <motion.span
          className={cn("font-medium tracking-tight select-none", s.text, reduce ? "text-neutral-400" : SHIMMER)}
          initial={reduce ? { opacity: 0.5 } : { backgroundPosition: "100% 0%" }}
          animate={reduce ? { opacity: [0.5, 1, 0.5] } : { backgroundPosition: ["100% 0%", "0% 0%"] }}
          transition={{ duration: reduce ? 2 : 1.8, repeat: Infinity, ease: reduce ? "easeInOut" : "linear" }}
        >
          {label}
        </motion.span>
      )}
    </span>
  );
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
